//! P4.3.4: the public catalogue repository's tooling.
//!
//! The repository holds only data (see `docs/marketplace/architecture.md`
//! §3 and `marketplace/catalogue-repository/`). Its CI runs the Patchwork
//! binary in its headless `catalogue` mode (`cli.rs`), so every check and
//! every generated byte comes from exactly the code the desktop app uses:
//! the same artifact format and ordering ([`super::submit::build_artifact`]),
//! the same SHA-256 rules, `parse_catalogue`, `parse_artifact`, the
//! capability scan, the secret scan and `check_refresh`. Nothing in a
//! package is ever constructed or evaluated: graphs are only read as JSON.
//!
//! ```text
//! publishers/<namespace>.json                  namespace claims (GitHub login + numeric id)
//! packages/<ns>/<name>/package.meta.json       listing metadata
//! packages/<ns>/<name>/README.md               optional
//! packages/<ns>/<name>/<version>/              one immutable version (the artifact's files,
//!                                              plus an optional preview.<png|jpg|jpeg|webp>)
//! moderation.json                              maintainer-only: withdrawn (yanked) versions
//! artifacts/<id>/<version>/<id>-<version>.pwpkg   generated by the publish workflow
//! index.json                                   generated by the publish workflow
//! ```
//!
//! **Pull requests** (`check_pull_request`) may only add a namespace claim
//! for the PR author's own GitHub account, or add new version folders and
//! listing metadata in a namespace that account owns. Existing versions,
//! claims, generated files and repository configuration are refused
//! (maintainer pull requests may change configuration, never generated
//! files or published bytes). The whole repository is then validated.
//!
//! **Publication** (after merge, on the default branch only): artifacts are
//! generated for new versions (an existing artifact must rebuild to the
//! same bytes, so published bytes can never be replaced) and committed;
//! the index is then generated with every new version's URL pinned to that
//! commit, while published versions keep their URLs. The new index must
//! pass `check_refresh` against the previous one.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use serde::Deserialize;

use super::limits::{MAX_ARTIFACT_FILE_BYTES, MAX_ARTIFACT_FILES, MAX_PREVIEW_BYTES};
use super::source::CatalogueLocation;
use super::{
    ARTIFACT_FORMAT, ArtifactEntry, Capability, Catalogue, CatalogueFile, PREVIEW_FILES,
    PackageEntry, PreviewEntry, PublisherEntry, RAW_HOST, VersionEntry, artifact_repo_path,
    check_artifact_listing, split_public_id,
};
use crate::library::package::{MANIFEST_FILE, PackageManifest, parse_stable_version};

pub mod cli;

pub const PUBLISHERS_DIR: &str = "publishers";
pub const PACKAGES_DIR: &str = "packages";
pub const ARTIFACTS_DIR: &str = "artifacts";
pub const INDEX_FILE: &str = "index.json";
pub const META_FILE: &str = "package.meta.json";
pub const PACKAGE_README: &str = "README.md";
pub const MODERATION_FILE: &str = "moderation.json";
/// A placeholder commit, used only to validate listings before
/// publication (never published).
const UNPUBLISHED_COMMIT: &str = "0000000000000000000000000000000000000000";

/// Problems found (all of them, not only the first).
pub type Issues = Vec<String>;

/// `package.meta.json`.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PackageMeta {
    pub name: String,
    #[serde(default)]
    pub description: String,
    pub author: String,
    #[serde(default)]
    pub tags: Vec<String>,
    #[serde(default)]
    pub license: Option<String>,
    #[serde(default)]
    pub documentation: Option<String>,
}

/// `moderation.json` (maintainer-only).
#[derive(Debug, Clone, Default, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
struct Moderation {
    /// `"<id>@<version>"` → reason. Not offered for new installs.
    #[serde(default)]
    yanked: BTreeMap<String, String>,
}

/// One version folder, read and checked.
#[derive(Debug, Clone)]
pub struct VersionSource {
    pub version: semver::Version,
    pub manifest: PackageManifest,
    pub min_patchwork: semver::Version,
    /// The artifact's files, in artifact order.
    pub files: Vec<(String, String)>,
    pub artifact: Vec<u8>,
    pub sha256: String,
    pub capabilities: BTreeSet<Capability>,
    /// `(file name, bytes)`.
    pub preview: Option<(String, Vec<u8>)>,
}

#[derive(Debug, Clone)]
pub struct PackageSource {
    pub id: String,
    pub namespace: String,
    pub name: String,
    pub meta: PackageMeta,
    pub versions: BTreeMap<semver::Version, VersionSource>,
}

/// The repository's data, read and checked.
#[derive(Debug, Clone, Default)]
pub struct Repository {
    pub publishers: BTreeMap<String, PublisherEntry>,
    pub packages: BTreeMap<String, PackageSource>,
    yanked: BTreeMap<String, String>,
}

fn sha256_hex(bytes: &[u8]) -> String {
    use sha2::{Digest, Sha256};
    Sha256::digest(bytes)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

/// Real directories and files only; a link anywhere is refused.
fn entries(dir: &Path, issues: &mut Issues) -> Vec<(String, bool, PathBuf)> {
    let mut out = Vec::new();
    let Ok(read) = std::fs::read_dir(dir) else {
        return out;
    };
    for entry in read.flatten() {
        let name = entry.file_name().to_string_lossy().into_owned();
        let Ok(kind) = entry.file_type() else {
            issues.push(format!("{}: cannot be read", entry.path().display()));
            continue;
        };
        if kind.is_symlink() {
            issues.push(format!(
                "{}: links are not allowed",
                rel_display(&entry.path())
            ));
            continue;
        }
        out.push((name, kind.is_dir(), entry.path()));
    }
    out.sort();
    out
}

fn rel_display(path: &Path) -> String {
    path.to_string_lossy().replace('\\', "/")
}

/// The image type a preview's bytes are, by their signature.
fn image_kind(bytes: &[u8]) -> Option<&'static str> {
    if bytes.starts_with(b"\x89PNG\r\n\x1a\n") {
        Some("png")
    } else if bytes.starts_with(&[0xFF, 0xD8, 0xFF]) {
        Some("jpeg")
    } else if bytes.len() >= 12 && &bytes[..4] == b"RIFF" && &bytes[8..12] == b"WEBP" {
        Some("webp")
    } else {
        None
    }
}

/// Check a preview image: allowed name, size, and bytes of that type.
pub fn check_preview(name: &str, bytes: &[u8]) -> Result<(), String> {
    if !PREVIEW_FILES.contains(&name) {
        return Err(format!("{name} is not an allowed preview name"));
    }
    if bytes.is_empty() || bytes.len() as u64 > MAX_PREVIEW_BYTES {
        return Err(format!(
            "{name} must be between 1 and {MAX_PREVIEW_BYTES} bytes"
        ));
    }
    let expected = match name.rsplit('.').next() {
        Some("png") => "png",
        Some("jpg" | "jpeg") => "jpeg",
        Some("webp") => "webp",
        _ => "",
    };
    if image_kind(bytes) != Some(expected) {
        return Err(format!("{name} is not a {expected} image"));
    }
    Ok(())
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Path) -> Result<T, String> {
    let meta = std::fs::symlink_metadata(path).map_err(|e| e.to_string())?;
    if !meta.is_file() || meta.len() > 1024 * 1024 {
        return Err("must be a regular file of at most 1 MiB".to_string());
    }
    let bytes = std::fs::read(path).map_err(|e| e.to_string())?;
    serde_json::from_slice(&bytes).map_err(|e| e.to_string())
}

/// Read one version folder (`packages/<ns>/<name>/<version>`).
fn read_version(
    id: &str,
    version: &semver::Version,
    dir: &Path,
    at: &str,
) -> Result<VersionSource, String> {
    let paths = super::submit::files_in(dir)?;
    let mut preview = None;
    let mut files = Vec::new();
    if paths.len() > MAX_ARTIFACT_FILES as usize + 1 {
        return Err(format!("{at}: more than {MAX_ARTIFACT_FILES} files"));
    }
    for path in &paths {
        let full = path.split('/').fold(dir.to_path_buf(), |p, s| p.join(s));
        let size = std::fs::metadata(&full).map_err(|e| e.to_string())?.len();
        if PREVIEW_FILES.contains(&path.as_str()) {
            if preview.is_some() {
                return Err(format!("{at}: more than one preview image"));
            }
            if size > MAX_PREVIEW_BYTES {
                return Err(format!(
                    "{at}/{path}: larger than {MAX_PREVIEW_BYTES} bytes"
                ));
            }
            let bytes = std::fs::read(&full).map_err(|e| e.to_string())?;
            check_preview(path, &bytes).map_err(|e| format!("{at}/{e}"))?;
            preview = Some((path.clone(), bytes));
            continue;
        }
        if size > MAX_ARTIFACT_FILE_BYTES {
            return Err(format!(
                "{at}/{path}: larger than {MAX_ARTIFACT_FILE_BYTES} bytes"
            ));
        }
        let bytes = std::fs::read(&full).map_err(|e| e.to_string())?;
        let text = String::from_utf8(bytes).map_err(|_| format!("{at}/{path}: not UTF-8 text"))?;
        files.push((path.clone(), text));
    }
    let manifest_text = files
        .iter()
        .find(|(p, _)| p == MANIFEST_FILE)
        .map(|(_, t)| t.as_str())
        .ok_or_else(|| format!("{at}: has no {MANIFEST_FILE}"))?;
    let manifest: PackageManifest = serde_json::from_str(manifest_text)
        .map_err(|e| format!("{at}/{MANIFEST_FILE}: not valid: {e}"))?;
    let parsed = manifest
        .validate()
        .map_err(|e| format!("{at}/{MANIFEST_FILE}: {e}"))?;
    if manifest.id != id || parsed != *version {
        return Err(format!(
            "{at}: {MANIFEST_FILE} describes {}@{parsed}, not the folder's {id}@{version}",
            manifest.id
        ));
    }
    let min_patchwork = manifest
        .min_app_version
        .as_deref()
        .ok_or_else(|| {
            format!("{at}/{MANIFEST_FILE}: must state min_app_version (the oldest Patchwork it supports)")
        })
        .and_then(|min| parse_stable_version(min).map_err(|e| format!("{at}: {e}")))?;
    check_artifact_listing(files.iter().map(|(p, _)| p.as_str()), &manifest.entry)
        .map_err(|e| format!("{at}: {e}"))?;
    super::submit::artifact_order(&mut files, &manifest.entry);
    let capabilities = super::submit::check_contents(&files).map_err(|e| format!("{at}: {e}"))?;
    let artifact = super::submit::build_artifact(id, version, &files);
    Ok(VersionSource {
        version: version.clone(),
        sha256: sha256_hex(&artifact),
        manifest,
        min_patchwork,
        files,
        artifact,
        capabilities,
        preview,
    })
}

/// Read the repository's data (publishers, packages, moderation). Every
/// problem is reported; generated files are not read here.
pub fn read_repository(root: &Path) -> Result<Repository, Issues> {
    let mut issues = Issues::new();
    let mut repository = Repository::default();

    for (name, is_dir, path) in entries(&root.join(PUBLISHERS_DIR), &mut issues) {
        if name == ".gitkeep" {
            continue;
        }
        let Some(namespace) = name.strip_suffix(".json").filter(|_| !is_dir) else {
            issues.push(format!(
                "{PUBLISHERS_DIR}/{name}: only <namespace>.json files belong here"
            ));
            continue;
        };
        match read_json::<PublisherEntry>(&path) {
            Ok(publisher) if publisher.namespace == namespace => {
                repository
                    .publishers
                    .insert(namespace.to_string(), publisher);
            }
            Ok(publisher) => issues.push(format!(
                "{PUBLISHERS_DIR}/{name}: claims namespace '{}'; the file must be named after it",
                publisher.namespace
            )),
            Err(e) => issues.push(format!("{PUBLISHERS_DIR}/{name}: {e}")),
        }
    }

    for (namespace, is_dir, ns_dir) in entries(&root.join(PACKAGES_DIR), &mut issues) {
        if namespace == ".gitkeep" {
            continue;
        }
        if !is_dir {
            issues.push(format!(
                "{PACKAGES_DIR}/{namespace}: only namespace folders belong here"
            ));
            continue;
        }
        for (name, is_dir, package_dir) in entries(&ns_dir, &mut issues) {
            let at = format!("{PACKAGES_DIR}/{namespace}/{name}");
            if !is_dir {
                issues.push(format!("{at}: only package folders belong here"));
                continue;
            }
            let id = format!("{namespace}.{name}");
            if let Err(e) = split_public_id(&id) {
                issues.push(format!("{at}: {e}"));
                continue;
            }
            let meta = match read_json::<PackageMeta>(&package_dir.join(META_FILE)) {
                Ok(meta) => meta,
                Err(e) => {
                    issues.push(format!("{at}/{META_FILE}: {e}"));
                    continue;
                }
            };
            let mut versions = BTreeMap::new();
            for (entry, is_dir, version_dir) in entries(&package_dir, &mut issues) {
                if !is_dir {
                    if entry != META_FILE && entry != PACKAGE_README {
                        issues.push(format!("{at}/{entry}: not part of a package folder"));
                    }
                    continue;
                }
                let version = match parse_stable_version(&entry) {
                    Ok(v) if v.to_string() == entry => v,
                    _ => {
                        issues.push(format!(
                            "{at}/{entry}: version folders are named MAJOR.MINOR.PATCH"
                        ));
                        continue;
                    }
                };
                match read_version(&id, &version, &version_dir, &format!("{at}/{entry}")) {
                    Ok(source) => {
                        versions.insert(version, source);
                    }
                    Err(e) => issues.push(e),
                }
            }
            if versions.is_empty() {
                issues.push(format!("{at}: has no version"));
                continue;
            }
            repository.packages.insert(
                id.clone(),
                PackageSource {
                    id,
                    namespace: namespace.clone(),
                    name,
                    meta,
                    versions,
                },
            );
        }
    }

    let moderation = root.join(MODERATION_FILE);
    if moderation.exists() {
        match read_json::<Moderation>(&moderation) {
            Ok(moderation) => repository.yanked = moderation.yanked,
            Err(e) => issues.push(format!("{MODERATION_FILE}: {e}")),
        }
    }
    for key in repository.yanked.keys() {
        let known = key.split_once('@').is_some_and(|(id, version)| {
            parse_stable_version(version).is_ok_and(|v| {
                repository
                    .packages
                    .get(id)
                    .is_some_and(|p| p.versions.contains_key(&v))
            })
        });
        if !known {
            issues.push(format!(
                "{MODERATION_FILE}: '{key}' is not a published version"
            ));
        }
    }

    if issues.is_empty() {
        Ok(repository)
    } else {
        Err(issues)
    }
}

/// Where a version's files are published (both pinned to a commit).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Pins {
    pub artifact_url: String,
    pub preview_url: Option<String>,
    pub published_at: Option<u64>,
}

fn raw_url(location: &CatalogueLocation, commit: &str, path: &str) -> String {
    format!(
        "https://{RAW_HOST}/{}/{}/{commit}/{path}",
        location.source().owner(),
        location.source().repo()
    )
}

/// Pins for a version published at `commit`.
pub fn pins_at(
    location: &CatalogueLocation,
    commit: &str,
    package: &PackageSource,
    version: &VersionSource,
    published_at: Option<u64>,
) -> Pins {
    Pins {
        artifact_url: raw_url(
            location,
            commit,
            &artifact_repo_path(&package.id, &version.version),
        ),
        preview_url: version.preview.as_ref().map(|(name, _)| {
            raw_url(
                location,
                commit,
                &format!(
                    "{PACKAGES_DIR}/{}/{}/{}/{name}",
                    package.namespace, package.name, version.version
                ),
            )
        }),
        published_at,
    }
}

/// The catalogue file for the repository, with each version's pins.
/// Everything is sorted (publishers by namespace, packages by id, versions
/// by version), so the same data always gives the same bytes.
pub fn catalogue_file(
    repository: &Repository,
    generated_at: Option<u64>,
    pins: impl Fn(&PackageSource, &VersionSource) -> Pins,
) -> CatalogueFile {
    CatalogueFile {
        kind: super::CATALOGUE_KIND.to_string(),
        catalogue_format: super::CATALOGUE_FORMAT,
        generated_at,
        publishers: repository.publishers.values().cloned().collect(),
        packages: repository
            .packages
            .values()
            .map(|package| PackageEntry {
                id: package.id.clone(),
                name: package.meta.name.clone(),
                description: package.meta.description.clone(),
                author: package.meta.author.clone(),
                tags: package.meta.tags.clone(),
                license: package.meta.license.clone(),
                documentation: package.meta.documentation.clone(),
                versions: package
                    .versions
                    .values()
                    .map(|version| {
                        let pins = pins(package, version);
                        VersionEntry {
                            version: version.version.to_string(),
                            entry: version.manifest.entry.clone(),
                            manifest_format: version.manifest.format,
                            pwnode_version: version.manifest.pwnode_version,
                            bundle_format: version.manifest.bundle_format,
                            min_patchwork: version.min_patchwork.to_string(),
                            capabilities: version
                                .capabilities
                                .iter()
                                .map(|c| c.as_str().to_string())
                                .collect(),
                            artifact: ArtifactEntry {
                                format: ARTIFACT_FORMAT,
                                url: pins.artifact_url,
                                sha256: version.sha256.clone(),
                                size: version.artifact.len() as u64,
                                files: version.files.len() as u32,
                            },
                            preview: version.preview.as_ref().zip(pins.preview_url).map(
                                |((_, bytes), url)| PreviewEntry {
                                    url,
                                    sha256: sha256_hex(bytes),
                                    size: bytes.len() as u64,
                                },
                            ),
                            published_at: pins.published_at,
                            yanked: repository
                                .yanked
                                .get(&format!("{}@{}", package.id, version.version))
                                .cloned(),
                        }
                    })
                    .collect(),
            })
            .collect(),
    }
}

fn parse(file: &CatalogueFile, location: &CatalogueLocation) -> Result<Catalogue, Issues> {
    let bytes = serde_json::to_vec(file).map_err(|e| vec![e.to_string()])?;
    super::parse_catalogue(&bytes, location.source()).map_err(|e| {
        let mut issues = vec![e.to_string()];
        issues.extend(e.issues.iter().cloned());
        issues
    })
}

/// The previously published index, if any (it must be valid).
pub fn previous_index(
    root: &Path,
    location: &CatalogueLocation,
) -> Result<Option<Catalogue>, Issues> {
    let path = root.join(INDEX_FILE);
    if !path.exists() {
        return Ok(None);
    }
    let bytes = std::fs::read(&path).map_err(|e| vec![format!("{INDEX_FILE}: {e}")])?;
    super::parse_catalogue(&bytes, location.source())
        .map(Some)
        .map_err(|e| vec![format!("{INDEX_FILE}: {e}")])
}

/// Validate the repository's data exactly as Patchwork validates what it
/// installs: the listing through `parse_catalogue` (namespaces, reserved
/// and look-alike names, one namespace per account, ids, versions, text
/// limits), every artifact through `verify_download` and `parse_artifact`
/// (paths, limits, manifest, checksums, bundled dependencies, secrets),
/// the capability scan, and each bundled dependency against the published
/// version it claims to be. With `previous`, published versions must be
/// unchanged (`check_refresh`).
pub fn validate(
    repository: &Repository,
    location: &CatalogueLocation,
    previous: Option<&Catalogue>,
) -> Result<Catalogue, Issues> {
    let file = catalogue_file(repository, None, |package, version| {
        pins_at(location, UNPUBLISHED_COMMIT, package, version, None)
    });
    let catalogue = parse(&file, location)?;
    let mut issues = Issues::new();
    for source in repository.packages.values() {
        let package = &catalogue.packages[&source.id];
        for version_source in source.versions.values() {
            let at = format!("{}@{}", source.id, version_source.version);
            let version = &package.versions[&version_source.version];
            let checked = super::artifact::verify_download(&version_source.artifact, version)
                .and_then(|()| {
                    super::artifact::parse_artifact(&version_source.artifact, package, version)
                })
                .and_then(|parsed| {
                    super::scan::check_declared(
                        &version.known_capabilities(),
                        &super::scan::scan_files(parsed.texts())?,
                    )
                });
            if let Err(e) = checked {
                issues.push(format!("{at}: {e}"));
            }
            // Bundled dependencies are exact copies of published versions
            // in this catalogue (never a forged or modified copy).
            for dependency in &version_source.manifest.dependencies {
                let Ok(dep_version) = parse_stable_version(&dependency.version) else {
                    issues.push(format!("{at}: invalid dependency version"));
                    continue;
                };
                let Some(published) = repository
                    .packages
                    .get(&dependency.id)
                    .and_then(|p| p.versions.get(&dep_version))
                else {
                    issues.push(format!(
                        "{at}: depends on {}@{dep_version}, which is not in the catalogue",
                        dependency.id
                    ));
                    continue;
                };
                let prefix = format!("deps/{}/{dep_version}/", dependency.id);
                for (path, text) in published
                    .files
                    .iter()
                    .filter(|(p, _)| p == MANIFEST_FILE || *p == published.manifest.entry)
                {
                    let bundled = version_source
                        .files
                        .iter()
                        .find(|(p, _)| *p == format!("{prefix}{path}"));
                    if bundled.map(|(_, t)| t) != Some(text) {
                        issues.push(format!(
                            "{at}: the bundled {}@{dep_version} differs from the published \
                             version ({path})",
                            dependency.id
                        ));
                    }
                }
            }
        }
    }
    if let Some(previous) = previous {
        // Published versions keep their bytes (identical artifact digest).
        if let Err(errors) = super::check_refresh(previous, &catalogue) {
            issues.extend(
                errors
                    .into_iter()
                    .filter(|e| !e.contains("generated_at"))
                    .map(|e| format!("published history: {e}")),
            );
        }
    }
    if issues.is_empty() {
        Ok(catalogue)
    } else {
        Err(issues)
    }
}

// ── Pull requests ────────────────────────────────────────────────────────

/// Every file of a checkout (`/`-separated), with its SHA-256; `.git` is
/// ignored. Links are reported.
fn tree(root: &Path, issues: &mut Issues) -> BTreeMap<String, String> {
    fn walk(root: &Path, dir: &Path, out: &mut BTreeMap<String, String>, issues: &mut Issues) {
        let Ok(read) = std::fs::read_dir(dir) else {
            return;
        };
        for entry in read.flatten() {
            let path = entry.path();
            let relative = path.strip_prefix(root).map(rel_display).unwrap_or_default();
            if relative == ".git" {
                continue;
            }
            match entry.file_type() {
                Ok(kind) if kind.is_symlink() => {
                    issues.push(format!("{relative}: links are not allowed"));
                }
                Ok(kind) if kind.is_dir() => walk(root, &path, out, issues),
                Ok(_) => {
                    let digest = std::fs::read(&path)
                        .map(|bytes| sha256_hex(&bytes))
                        .unwrap_or_default();
                    out.insert(relative, digest);
                }
                Err(e) => issues.push(format!("{relative}: {e}")),
            }
        }
    }
    let mut out = BTreeMap::new();
    walk(root, root, &mut out, issues);
    out
}

/// Who opened the pull request, as GitHub reports it (from the event,
/// never from the pull request's content).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Author {
    pub login: String,
    pub id: u64,
    /// The repository's maintainers may change configuration (never
    /// generated files or published bytes).
    pub maintainer: bool,
}

/// What a pull request adds.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PullRequestReport {
    pub new_publishers: Vec<String>,
    pub new_versions: Vec<String>,
    pub changed: Vec<String>,
}

/// Check a pull request: `base` is the target branch's checkout, `head`
/// the merge result. Only the PR author's own additions are accepted; then
/// the whole head repository must validate against the published index.
pub fn check_pull_request(
    base: &Path,
    head: &Path,
    location: &CatalogueLocation,
    author: &Author,
) -> Result<PullRequestReport, Issues> {
    let mut issues = Issues::new();
    let before = tree(base, &mut issues);
    let after = tree(head, &mut issues);
    let changed: BTreeSet<&String> = before
        .keys()
        .chain(after.keys())
        .filter(|path| before.get(*path) != after.get(*path))
        .collect();
    let head_repository = read_repository(head);
    let owners: BTreeMap<String, u64> = match &head_repository {
        Ok(repository) => repository
            .publishers
            .iter()
            .map(|(ns, p)| (ns.clone(), p.github_id))
            .collect(),
        Err(_) => BTreeMap::new(),
    };
    let mut report = PullRequestReport::default();
    let mut new_versions = BTreeSet::new();
    for path in &changed {
        let segments: Vec<&str> = path.split('/').collect();
        let added = !before.contains_key(*path);
        let removed = !after.contains_key(*path);
        report.changed.push((*path).clone());
        match segments.as_slice() {
            [first, ..] if *first == ARTIFACTS_DIR || **path == INDEX_FILE => issues.push(format!(
                "{path}: generated by the publish workflow; never edited in a pull request"
            )),
            [dir, file] if *dir == PUBLISHERS_DIR => {
                let namespace = file.strip_suffix(".json").unwrap_or(file);
                if !added {
                    if !author.maintainer {
                        issues.push(format!(
                            "{path}: an existing namespace claim can only be changed by the \
                             maintainers"
                        ));
                    }
                    continue;
                }
                if author.maintainer && !namespace.eq_ignore_ascii_case(&author.login) {
                    // Maintainers may register a namespace for its owner;
                    // the claim itself is still validated below.
                    report.new_publishers.push(namespace.to_string());
                    continue;
                }
                let claim = head_repository
                    .as_ref()
                    .ok()
                    .and_then(|r| r.publishers.get(namespace));
                match claim {
                    Some(claim)
                        if claim.github.eq_ignore_ascii_case(&author.login)
                            && claim.github_id == author.id =>
                    {
                        report.new_publishers.push(namespace.to_string())
                    }
                    Some(_) => issues.push(format!(
                        "{path}: a namespace can only be claimed for the pull request's own \
                         GitHub account (@{}, id {})",
                        author.login, author.id
                    )),
                    None => {} // reported by the validation below
                }
            }
            [dir, namespace, rest @ ..] if *dir == PACKAGES_DIR && !rest.is_empty() => {
                if !author.maintainer && owners.get(*namespace) != Some(&author.id) {
                    issues.push(format!(
                        "{path}: namespace '{namespace}' does not belong to @{} (id {}); \
                         claim it in publishers/{namespace}.json from that account",
                        author.login, author.id
                    ));
                }
                // An existing version folder never changes.
                if let [name, version, ..] = rest {
                    if rest.len() >= 3 {
                        let version_dir = base
                            .join(PACKAGES_DIR)
                            .join(namespace)
                            .join(name)
                            .join(version);
                        if version_dir.exists() {
                            if !(author.maintainer && removed) {
                                issues.push(format!(
                                    "{path}: {namespace}.{name}@{version} is published; \
                                     published versions never change (add a new version)"
                                ));
                            }
                        } else if added {
                            new_versions.insert(format!("{namespace}.{name}@{version}"));
                        }
                    }
                }
                if removed && !author.maintainer {
                    issues.push(format!("{path}: removing files needs the maintainers"));
                }
            }
            _ if author.maintainer => {}
            _ => issues.push(format!(
                "{path}: only the maintainers change this file; submissions add files under \
                 {PUBLISHERS_DIR}/ and {PACKAGES_DIR}/"
            )),
        }
    }
    report.new_versions = new_versions.into_iter().collect();
    if let Ok(repository) = &head_repository {
        // A version taken down (folder removed) keeps its artifact; it can
        // only come back with exactly the same bytes.
        for package in repository.packages.values() {
            for version in package.versions.values() {
                let published = artifact_file(base, &package.id, &version.version);
                if let Ok(bytes) = std::fs::read(&published) {
                    if bytes != version.artifact {
                        issues.push(format!(
                            "{}@{}: differs from its published artifact; published bytes                              are never replaced",
                            package.id, version.version
                        ));
                    }
                }
            }
        }
    }
    match &head_repository {
        Ok(repository) => {
            let previous = previous_index(base, location);
            match previous {
                Ok(previous) => {
                    if let Err(errors) = validate(repository, location, previous.as_ref()) {
                        issues.extend(errors);
                    }
                }
                Err(errors) => issues.extend(errors),
            }
        }
        Err(errors) => issues.extend(errors.iter().cloned()),
    }
    if issues.is_empty() {
        Ok(report)
    } else {
        Err(issues)
    }
}

// ── Publication (trusted CI on the default branch) ──────────────────────

fn artifact_file(root: &Path, id: &str, version: &semver::Version) -> PathBuf {
    artifact_repo_path(id, version)
        .split('/')
        .fold(root.to_path_buf(), |p, s| p.join(s))
}

/// Generate the artifacts of new versions. An artifact that exists must
/// rebuild to exactly its bytes (published bytes are never replaced).
/// Returns the artifacts written (repository-relative paths).
pub fn publish_artifacts(root: &Path, location: &CatalogueLocation) -> Result<Vec<String>, Issues> {
    let repository = read_repository(root)?;
    let previous = previous_index(root, location)?;
    validate(&repository, location, previous.as_ref())?;
    let mut issues = Issues::new();
    let mut pending = Vec::new();
    for package in repository.packages.values() {
        for version in package.versions.values() {
            let path = artifact_file(root, &package.id, &version.version);
            let relative = artifact_repo_path(&package.id, &version.version);
            match std::fs::symlink_metadata(&path) {
                Ok(meta) if meta.is_file() => {
                    if std::fs::read(&path).ok().as_deref() != Some(version.artifact.as_slice()) {
                        issues.push(format!(
                            "{relative}: differs from the artifact built from its version \
                             folder; published bytes are never replaced"
                        ));
                    }
                }
                Ok(_) => issues.push(format!("{relative}: is not a regular file")),
                Err(_) => pending.push((path, relative, &version.artifact)),
            }
        }
    }
    if !issues.is_empty() {
        return Err(issues);
    }
    let mut written = Vec::new();
    for (path, relative, bytes) in pending {
        let write = || -> std::io::Result<()> {
            let dir = path.parent().expect("artifact paths have a folder");
            std::fs::create_dir_all(dir)?;
            let temp = dir.join(".artifact.tmp");
            std::fs::write(&temp, bytes)?;
            std::fs::rename(&temp, &path)
        };
        write().map_err(|e| vec![format!("{relative}: {e}")])?;
        written.push(relative);
    }
    Ok(written)
}

/// Generate `index.json`. Published versions keep their pins; new ones are
/// pinned to `commit` (the commit that added their artifacts) and must have
/// their artifact in `root`. `generated_at` never goes backwards. The
/// result must pass the desktop's own `parse_catalogue` and `check_refresh`.
pub fn publish_index(
    root: &Path,
    location: &CatalogueLocation,
    commit: &str,
    generated_at: u64,
) -> Result<Vec<u8>, Issues> {
    if commit.len() != 40
        || !commit
            .chars()
            .all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase())
        || commit == UNPUBLISHED_COMMIT
    {
        return Err(vec![
            "--commit must be a full 40-character commit hash".to_string(),
        ]);
    }
    let repository = read_repository(root)?;
    let previous = previous_index(root, location)?;
    validate(&repository, location, previous.as_ref())?;
    let mut issues = Issues::new();
    for package in repository.packages.values() {
        for version in package.versions.values() {
            let published = previous
                .as_ref()
                .and_then(|p| p.version(&package.id, &version.version))
                .is_some();
            let path = artifact_file(root, &package.id, &version.version);
            if !published
                && std::fs::read(&path).ok().as_deref() != Some(version.artifact.as_slice())
            {
                issues.push(format!(
                    "{}: generate the artifacts (and commit them) before the index",
                    artifact_repo_path(&package.id, &version.version)
                ));
            }
        }
    }
    if !issues.is_empty() {
        return Err(issues);
    }
    let generated_at = previous
        .as_ref()
        .and_then(|p| p.generated_at)
        .map_or(generated_at, |before| before.max(generated_at));
    let file = catalogue_file(
        &repository,
        Some(generated_at),
        |package, version| match previous
            .as_ref()
            .and_then(|p| p.version(&package.id, &version.version))
        {
            Some(published) => Pins {
                artifact_url: published.artifact.url.clone(),
                preview_url: published.preview.as_ref().map(|p| p.url.clone()),
                published_at: published.published_at,
            },
            None => pins_at(location, commit, package, version, Some(generated_at)),
        },
    );
    let next = parse(&file, location)?;
    if let Some(previous) = &previous {
        super::check_refresh(previous, &next).map_err(|errors| {
            errors
                .into_iter()
                .map(|e| format!("published history: {e}"))
                .collect::<Vec<_>>()
        })?;
    }
    let mut bytes = serde_json::to_vec_pretty(&file).map_err(|e| vec![e.to_string()])?;
    bytes.push(b'\n');
    Ok(bytes)
}

